const services = [
  { name: 'macro_service',     url: 'http://host.docker.internal:8001/api/health' },
  { name: 'risk_service',      url: 'http://host.docker.internal:8002/api/health' },
  { name: 'execution_service', url: 'http://host.docker.internal:8003/api/health' },
  { name: 'signal_service',    url: 'http://host.docker.internal:8004/api/health' },
  { name: 'xauusd_service',    url: 'http://host.docker.internal:8005/api/health' }
];
const results = [];
for (const svc of services) {
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: svc.url, timeout: 5000 });
    let extra = '';
    if (svc.name === 'execution_service' && r.daily_pnl_pct != null) {
      extra = ' pnl=' + (r.daily_pnl_pct * 100).toFixed(2) + '%';
    }
    if (svc.name === 'signal_service') {
      extra = ' ' + (r.model || '?') + ' buf=' + (r.buffer_size || 0) + '/60';
      if (r.collapse_alert) extra += ' COLLAPSE!';
    }
    if (svc.name === 'xauusd_service') {
      extra = ' xau=$' + (r.last_price || 0).toFixed(1);
    }
    results.push({ name: svc.name, ok: r.status === 'healthy', latency: r.latency_ms, extra });
  } catch(e) {
    results.push({ name: svc.name, ok: false, latency: null, extra: '', error: e.message });
  }
}
const failed = results.filter(r => !r.ok);
const allOk = failed.length === 0;
const lines = results.map(r =>
  (r.ok ? '\u2705' : '\u274c') + ' ' + r.name +
  (r.latency ? ' \u2014 ' + r.latency + 'ms' : ' \u2014 DOWN') +
  r.extra
);
const ts = new Date().toISOString().replace('T',' ').substring(0,19) + ' UTC';
return [{ json: { allOk, failedNames: failed.map(f=>f.name).join(', '), message: lines.join('\n'), timestamp: ts } }];
